@Catch() // TRỐNG = bắt MỌI exception
catch(err, host) {
  const isHttp =
    err instanceof HttpException;
  // 404 chủ động giữ status của nó
  const status =
    isHttp ? err.getStatus() : 500;
  const message = isHttp ? err.message
    : 'Có lỗi phía server, thử lại sau';
  // stack chỉ log SERVER-side
  console.error('[S6]', err.stack);
  res.status(status).json({
    code: isHttp ? status : 'INTERNAL',
    message, path, timestamp });
